mapper.select:
SELECT a.id, a.user_id, u.nickname AS author_nickname, u.avatar AS author_avatar, a.title, a.summary, a.cover, a.category_id, c.name AS category_name, c.slug AS category_slug, a.status, a.is_top, a.allow_comment, a.view_count, a.like_count, a.comment_count, a.publish_time, a.create_time, a.update_time FROM article a LEFT JOIN user u ON u.id = a.user_id AND u.deleted = 0 LEFT JOIN category c ON c.id = a.category_id AND c.deleted = 0 WHERE a.deleted = 0
AND a.status = #{query.status}
AND a.user_id = #{query.userId}
AND a.category_id = #{query.categoryId}
AND EXISTS ( SELECT 1 FROM article_tag at WHERE at.article_id = a.id AND at.tag_id = #{query.tagId} )
AND (a.title LIKE CONCAT('%', #{query.keyword}, '%') OR a.summary LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY
a.view_count a.like_count a.is_top DESC, a.publish_time
ASC DESC
